const STOP = new Set(
  ("the and that for with this from have been were which shall not but his her its into upon such under any all was are had has where when who whom would could should also more than then there their them they said case court judgment paragraph section learned counsel submitted accordingly therefore however further whether above before after other same must does made make being"
  ).split(/\s+/)
);

// Matches words in any script: Latin, Thaana, Arabic, Devanagari.
// \p{M} keeps Thaana fili and Arabic diacritics attached to their letter.
const TOKEN = /[\p{L}][\p{L}\p{M}]{2,}/gu;

const wordsOf = (t) =>
  Array.from(new Set((String(t).toLowerCase().match(TOKEN) || []).filter((w) => !STOP.has(w))));

const termsOf = (t) => wordsOf(t).slice(0, 400);

const splitParas = (text) => {
  const out = [];
  String(text)
    .split(/\n+/)
    .map((s) => s.trim())
    .filter((s) => s.length > 60)
    .forEach((b, i) => {
      const m = b.match(/^\[?(\d{1,3})[\.\)\]]\s+/);
      out.push({ n: m ? m[1] : String(i + 1), numbered: !!m, text: b.slice(0, 1400) });
    });
  return out;
};

